entries.syntax:
struct NAME { FIELD: TYPE }
impl NAME {
    fn METHOD(&self) { ... }
}

examples:
struct Rect { w: u32, h: u32 }
impl Rect {
    fn area(&self) -> u32 { self.w * self.h }
}
let r = Rect { w: 2, h: 3 };
println!("{}", r.area());

entries.syntax:
match VALUE {
    PATTERN if GUARD => EXPRESSION,
    _ => EXPRESSION,
}

examples:
let pair = (0, 5);
match pair {
    (0, y) => println!("x는 0, y={}", y),
    (x, 0) => println!("x={}", x),
    _ => println!("그 외"),
}

entries.syntax:
trait NAME {
    fn METHOD(&self) -> TYPE;
}
impl NAME for TYPE {
    fn METHOD(&self) -> TYPE { ... }
}

examples:
trait Area { fn area(&self) -> f64; }
struct Square(f64);
impl Area for Square {
    fn area(&self) -> f64 { self.0 * self.0 }
}
fn show<T: Area>(x: &T) { println!("{}", x.area()); }
show(&Square(2.0));

let double = |n: i32| n * 2;
let nums = vec![1, 2, 3];
let doubled: Vec<i32> = nums.iter().map(|n| double(*n)).collect();
println!("{:?}", doubled);

entries.syntax:
enum NAME {
    UNIT,
    TUPLE(TYPE),
    STRUCT { FIELD: TYPE },
}

examples:
enum Message {
    Quit,
    Move { x: i32, y: i32 },
    Write(String),
}
let m = Message::Move { x: 1, y: 2 };
if let Message::Move { x, y } = m {
    println!("{} {}", x, y);
}
